contracts/LiquidityHub.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.28;

import {
    IERC20,
    IERC20Metadata,
    ERC20Upgradeable,
    ERC4626Upgradeable,
    SafeERC20,
    Math
} from "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC4626Upgradeable.sol";
import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";
import {AccessControlUpgradeable} from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import {ERC7201Helper} from "./utils/ERC7201Helper.sol";
import {IManagedToken} from "./interfaces/IManagedToken.sol";
import {ILiquidityPool} from "./interfaces/ILiquidityPool.sol";
import {ILiquidityHub} from "./interfaces/ILiquidityHub.sol";

/// @title A modified version of the ERC4626 vault with the following key differences:
/// 1. The shares token functionality is delegated to a dedicated token contract.
/// 2. The total assets variable cannot be increased by a donation, making inflation by users impossible.
/// 3. The total assets could be increased or decreased by an Adjuster role to modify the conversion rate.
/// 4. Has an admin controlled maximum total assets limit.
/// 5. Supports deposit with permit if the underlying asset supports permit as well.
/// 6. Underlying assets are deposited/withdrawn to/from a connected ILiquidityPool contract.
/// 7. To withdraw/redeem on behalf, owner has to approve spender on the shares contract instead of this one.
/// 8. The shares token could have greater decimals value than the underlying assets.
/// @notice Upgradeable.
/// @notice After doing an initial deposit, send a trivial amount of LP tokens to a dead address.
/// This will make sure that share-price rate reset cannot happen in the future.
/// @author Oleksii Matiiasevych <oleksii@chainsafe.io>
contract LiquidityHub is ILiquidityHub, ERC4626Upgradeable, AccessControlUpgradeable {
    using Math for uint256;

    IManagedToken immutable public SHARES;
    ILiquidityPool immutable public LIQUIDITY_POOL;
    bytes32 public constant ASSETS_ADJUST_ROLE = "ASSETS_ADJUST_ROLE";
    bytes32 public constant DEPOSIT_PROFIT_ROLE = "DEPOSIT_PROFIT_ROLE";
    bytes32 public constant SET_ASSETS_LIMIT_ROLE = "SET_ASSETS_LIMIT_ROLE";
    bytes32 public constant FULFIL_REDEEM_ROLE = "FULFIL_REDEEM_ROLE";

    event TotalAssetsAdjustment(uint256 oldAssets, uint256 newAssets);
    event AssetsLimitSet(uint256 oldLimit, uint256 newLimit);
    event DepositProfit(address caller, uint256 assets);
    event RedeemRequest(
        address indexed controller, address indexed owner, uint256 indexed requestId,
        address sender, uint256 shares
    );
    event OperatorSet(address indexed owner, address indexed operator, bool approved);

    error ZeroAddress();
    error NotImplemented();
    error IncompatibleAssetsAndShares();
    error AssetsLimitIsTooBig();
    error EmptyHub();
    error AssetsExceedHardLimit();
    error InvalidAdjustment();

    /// @custom:storage-location erc7201:sprinter.storage.LiquidityHub
    struct LiquidityHubStorage {
        uint256 totalAssets;
        uint256 assetsLimit;
        uint256 totalRedeemRequest;
        mapping(address controller => uint256 shares) redeemRequests;
        mapping(address ownerOrController => mapping(address operator => bool)) operators;
    }

    bytes32 private constant STORAGE_LOCATION = 0xb877bfaae1674461dd1960c90f24075e3de3265a91f6906fe128ab8da6ba1700;

    constructor(address shares, address liquidityPool) {
        ERC7201Helper.validateStorageLocation(
            STORAGE_LOCATION,
            "sprinter.storage.LiquidityHub"
        );
        require(shares != address(0), ZeroAddress());
        require(liquidityPool != address(0), ZeroAddress());
        SHARES = IManagedToken(shares);
        LIQUIDITY_POOL = ILiquidityPool(liquidityPool);
        _disableInitializers();
    }

    function initialize(
        IERC20 asset_,
        address admin,
        address adjuster,
        address depositorProfit,
        address assetsLimitSetter,
        uint256 newAssetsLimit
    ) external initializer() {
        ERC4626Upgradeable.__ERC4626_init(asset_);
        require(
            IERC20Metadata(address(asset_)).decimals() <= IERC20Metadata(address(SHARES)).decimals(),
            IncompatibleAssetsAndShares()
        );
        // Deliberately not initializing ERC20Upgradable because its
        // functionality is delegated to SHARES.
        require(admin != address(0), ZeroAddress());
        require(adjuster != address(0), ZeroAddress());
        require(depositorProfit != address(0), ZeroAddress());
        require(assetsLimitSetter != address(0), ZeroAddress());
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(ASSETS_ADJUST_ROLE, adjuster);
        _grantRole(DEPOSIT_PROFIT_ROLE, depositorProfit);
        _grantRole(SET_ASSETS_LIMIT_ROLE, assetsLimitSetter);
        _setAssetsLimit(newAssetsLimit);
    }

    function supportsInterface(bytes4 interfaceId) public view override returns (bool) {
        return super.supportsInterface(interfaceId)
            || interfaceId == 0x620ee8e4 // Asynchronous redemption
            || interfaceId == 0xe3bc4e65 // Operator methods
            || interfaceId == 0x2f0a18c5; // ERC-7575, share() method
    }

    function adjustTotalAssets(uint256 amount, bool isIncrease) external onlyRole(ASSETS_ADJUST_ROLE) {
        LiquidityHubStorage storage $ = _getStorage();
        uint256 assets = $.totalAssets;
        require(assets > 0, EmptyHub());
        uint256 newAssets;
        if (isIncrease) {
            require(amount <= _assetsIncreaseHardLimit(assets), AssetsExceedHardLimit());
            newAssets = assets + amount;
        } else {
            newAssets = assets - amount;
        }
        require(newAssets > 0 || totalSupply() == 0, InvalidAdjustment());
        $.totalAssets = newAssets;
        emit TotalAssetsAdjustment(assets, newAssets);
    }

    function setAssetsLimit(uint256 newAssetsLimit) external onlyRole(SET_ASSETS_LIMIT_ROLE) {
        _setAssetsLimit(newAssetsLimit);
    }

    function _setAssetsLimit(uint256 newAssetsLimit) internal {
        require(newAssetsLimit <= type(uint256).max / 10 ** _decimalsOffset(), AssetsLimitIsTooBig());
        LiquidityHubStorage storage $ = _getStorage();
        uint256 oldLimit = $.assetsLimit;
        $.assetsLimit = newAssetsLimit;
        emit AssetsLimitSet(oldLimit, newAssetsLimit);
    }

    function share() external view returns (address shareTokenAddress) {
        return address(SHARES);
    }

    function name() public pure override(IERC20Metadata, ERC20Upgradeable) returns (string memory) {
        revert NotImplemented();
    }

    function symbol() public pure override(IERC20Metadata, ERC20Upgradeable) returns (string memory) {
        revert NotImplemented();
    }

    function decimals() public pure override returns (uint8) {
        revert NotImplemented();
    }

    function totalSupply() public view virtual override(IERC20, ERC20Upgradeable) returns (uint256) {
        return IERC20(address(SHARES)).totalSupply() + totalRedeemRequest();
    }

    function totalRedeemRequest() public view returns (uint256) {
        return _getStorage().totalRedeemRequest;
    }

    function balanceOf(address owner) public view virtual override(IERC20, ERC20Upgradeable) returns (uint256) {
        return IERC20(address(SHARES)).balanceOf(owner);
    }

    function transfer(address, uint256) public pure override(IERC20, ERC20Upgradeable) returns (bool) {
        revert NotImplemented();
    }

    function allowance(address, address) public pure override(IERC20, ERC20Upgradeable) returns (uint256) {
        // Silences the unreachable code warning from ERC20Upgradeable._spendAllowance().
        return 0;
    }

    function approve(address, uint256) public pure override(IERC20, ERC20Upgradeable) returns (bool) {
        revert NotImplemented();
    }

    function transferFrom(address, address, uint256) public pure override(IERC20, ERC20Upgradeable) returns (bool) {
        revert NotImplemented();
    }

    function totalAssets() public view virtual override returns (uint256) {
        return _getStorage().totalAssets;
    }

    function assetsLimit() public view returns (uint256) {
        return _getStorage().assetsLimit;
    }

    function maxDeposit(address) public view virtual override returns (uint256) {
        uint256 total = totalAssets();
        uint256 limit = assetsLimit();
        if (total >= limit) {
            return 0;
        }
        uint256 hardLimit = _assetsIncreaseHardLimit(total);
        return Math.min(hardLimit, limit - total);
    }

    function maxMint(address) public view virtual override returns (uint256) {
        return _convertToShares(maxDeposit(address(0)), Math.Rounding.Floor);
    }

    // Note, a malicious actor could frontrun the permit() call in separate transaction, which will
    // make this transaction revert. It is an unlikely possibility because there is no gain in it.
    // If such frontrun did happen, a user can proceed with a simple deposit() as the allowance would
    // already be given.
    function depositWithPermit(
        uint256 assets,
        address receiver,
        uint256 deadline,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external {
        IERC20Permit(asset()).permit(
            _msgSender(),
            address(this),
            assets,
            deadline,
            v,
            r,
            s
        );
        deposit(assets, receiver);
    }

    function depositProfit(uint256 assets) external onlyRole(DEPOSIT_PROFIT_ROLE) {
        LiquidityHubStorage storage $ = _getStorage();
        SafeERC20.safeTransferFrom(IERC20(asset()), _msgSender(), address(LIQUIDITY_POOL), assets);
        uint256 currentAssets = $.totalAssets;
        require(currentAssets > 0, EmptyHub());
        require(assets <= _assetsIncreaseHardLimit(currentAssets), AssetsExceedHardLimit());
        uint256 newAssets = currentAssets + assets;
        $.totalAssets = newAssets;
        LIQUIDITY_POOL.deposit(assets);
        emit DepositProfit(_msgSender(), assets);
    }

    function setOperator(address operator, bool approved) public returns (bool) {
        _getStorage().operators[_msgSender()][operator] = approved;
        emit OperatorSet(_msgSender(), operator, approved);
        return true;
    }

    function isOperator(address controller, address operator) public view returns (bool) {
        return _getStorage().operators[controller][operator];
    }

    function requestRedeem(uint256 shares, address controller, address owner) external returns (uint256 requestId) {
        require(controller != address(0), ZeroAddress());
        return _requestRedeem(shares, controller, owner, _msgSender());
    }

    function requestRedeemWithFulfil(uint256 shares) external returns (uint256 requestId) {
        setOperator(address(this), true);
        return _requestRedeem(shares, _msgSender(), _msgSender(), _msgSender());
    }

    function _requestRedeem(uint256 shares, address controller, address owner, address caller)
        internal returns (uint256 requestId)
    {
        LiquidityHubStorage storage $ = _getStorage();
        bool ownerOrOperator = caller == owner || isOperator(owner, caller);
        if (!ownerOrOperator) {
            _spendAllowance(owner, caller, shares);
        }
        _burn(owner, shares);
        $.redeemRequests[controller] += shares;
        $.totalRedeemRequest += shares;
        emit RedeemRequest(controller, owner, 0, caller, shares);
        return 0;
    }

    function claimableRedeemRequest(uint256 /* requestId */, address controller) public view returns (uint256) {
        uint256 pending = _getStorage().redeemRequests[controller];
        if (pending == 0) return 0;
        uint256 availableAssets = _availableAssets();
        uint256 availableShares = _convertToShares(availableAssets, Math.Rounding.Floor);
        return Math.min(pending, availableShares);
    }

    function pendingRedeemRequest(uint256 /* requestId */, address controller) external view returns (uint256) {
        return _getStorage().redeemRequests[controller] - claimableRedeemRequest(0, controller);
    }

    function fulfilRedeem(address[] calldata receivers) external onlyRole(FULFIL_REDEEM_ROLE) {
        for (uint256 i = 0; i < receivers.length; i++) {
            address receiver = receivers[i];
            uint256 shares = claimableRedeemRequest(0, receiver);
            if (shares == 0) continue;
            this.redeem(shares, receiver, receiver);
        }
    }

    function maxRedeem(address owner) public view override returns (uint256) {
        uint256 totalShares = balanceOf(owner) + _getStorage().redeemRequests[owner];
        uint256 total = _convertToAssets(totalShares, Math.Rounding.Floor);
        uint256 availableAssets = _availableAssets();
        if (total > availableAssets) {
            return _convertToShares(availableAssets, Math.Rounding.Floor);
        }
        return totalShares;
    }

    function maxWithdraw(address owner) public view override returns (uint256) {
        uint256 totalShares = balanceOf(owner) + _getStorage().redeemRequests[owner];
        uint256 total = _convertToAssets(totalShares, Math.Rounding.Floor);
        uint256 availableAssets = _availableAssets();
        return Math.min(total, availableAssets);
    }

    function _convertToShares(uint256 assets, Math.Rounding rounding) internal view virtual override returns (uint256) {
        (uint256 supplyShares, uint256 supplyAssets) = _getTotalsForConversion();
        return assets.mulDiv(supplyShares, supplyAssets, rounding);
    }

    function _convertToAssets(uint256 shares, Math.Rounding rounding) internal view virtual override returns (uint256) {
        (uint256 supplyShares, uint256 supplyAssets) = _getTotalsForConversion();
        return shares.mulDiv(supplyAssets, supplyShares, rounding);
    }

    function _getTotalsForConversion() internal view returns (uint256, uint256) {
        uint256 supplyShares = totalSupply();
        uint256 supplyAssets = totalAssets();
        if (supplyShares == 0) {
            supplyShares = 10 ** _decimalsOffset();
        }
        if (supplyAssets == 0) {
            supplyAssets = 1;
        }
        return (supplyShares, supplyAssets);
    }

    function _update(address from, address to, uint256 value) internal virtual override {
        if (from == address(0)) {
            SHARES.mint(to, value);
        } else if (to == address(0)) {
            SHARES.burn(from, value);
        } else {
            revert NotImplemented();
        }
    }

    function _spendAllowance(address owner, address spender, uint256 value) internal virtual override {
        SHARES.spendAllowance(owner, spender, value);
    }

    /// OpenZeppelin's implementation of ERC20 token (used as shares) doesn't revert if _mint() is called with 0 amount
    /// Therefore it's possible that a user deposits less than the price of 1 share and 0 shares will be minted.
    /// It might happen only if deposit is very small (1 unit of token) and the balance of shares was significantly
    /// shifted using adjustTotalAssets(). This situation was modelled with usual and fuzz testing and no protection
    /// was added due to insignificant consequences.
    function _deposit(address caller, address receiver, uint256 assets, uint256 shares) internal virtual override {
        LiquidityHubStorage storage $ = _getStorage();
        SafeERC20.safeTransferFrom(IERC20(asset()), caller, address(LIQUIDITY_POOL), assets);
        _mint(receiver, shares);
        $.totalAssets += assets;
        LIQUIDITY_POOL.deposit(assets);
        emit Deposit(caller, receiver, assets, shares);
    }

    function _withdraw(
        address caller,
        address receiver,
        address owner,
        uint256 assets,
        uint256 shares
    ) internal virtual override {
        LiquidityHubStorage storage $ = _getStorage();
        $.totalAssets -= assets;
        uint256 fromPending;
        bool ownerOrOperator = caller == owner || isOperator(owner, caller);
        // Skip the async flow in case of allowance based redemption.
        if (ownerOrOperator) {
            uint256 pending = $.redeemRequests[owner];
            fromPending = Math.min(pending, shares);
            if (fromPending > 0) {
                $.redeemRequests[owner] = pending - fromPending;
                $.totalRedeemRequest -= fromPending;
            }
        }
        uint256 fromOwner = shares - fromPending;
        if (fromOwner > 0) {
            if (!ownerOrOperator) {
                _spendAllowance(owner, caller, fromOwner);
            }
            _burn(owner, fromOwner);
        }
        LIQUIDITY_POOL.withdraw(receiver, assets);
        emit Withdraw(caller, receiver, owner, assets, shares);
    }

    function _decimalsOffset() internal view virtual override returns (uint8) {
        return IERC20Metadata(address(SHARES)).decimals() - IERC20Metadata(asset()).decimals();
    }

    function _assetsIncreaseHardLimit(uint256 total) internal view returns (uint256) {
        uint256 totalShares = totalSupply();
        uint256 multiplier = uint256(10) ** _decimalsOffset();
        if (total * multiplier <= totalShares) {
            uint256 sharesHardLimit = type(uint256).max - totalShares;
            return _convertToAssets(sharesHardLimit, Math.Rounding.Floor);
        } else {
            return type(uint256).max / multiplier - total;
        }
    }

    /// @notice ILiquidityPool.balance() can underreport withdrawable assets in certain pools (eg. Aave),
    /// if that ever causes a problem, Liquidity Pool can be changed to the simple one, that does not underreport,
    /// or another solution could be implemented, like a specific function that returns withdrawable balance.
    function _availableAssets() internal view returns (uint256) {
        return Math.min(LIQUIDITY_POOL.balance(IERC20(asset())), LIQUIDITY_POOL.totalDeposited());
    }

    function _getStorage() private pure returns (LiquidityHubStorage storage $) {
        assembly {
            $.slot := STORAGE_LOCATION
        }
    }
}

contracts/utils/ERC7201Helper.sol.content:
// SPDX-License-Identifier: LGPL-3.0-only
pragma solidity 0.8.28;

library ERC7201Helper {
    error InvalidStorageSlot(string namespace);

    function validateStorageLocation(bytes32 actual, string memory namespace) internal pure {
        bytes32 expected = getStorageLocation(bytes(namespace));
        require(actual == expected, InvalidStorageSlot(namespace));
    }

    function getStorageLocation(bytes memory namespace) internal pure returns(bytes32) {
        return keccak256(abi.encode(uint256(keccak256(namespace)) - 1)) & ~bytes32(uint256(0xff));
    }
}
